<script>document.querySelectorAll('[data-purchase-line]').forEach((line)=>{const select=line.querySelector('[data-tax-code]');const fields=line.querySelector('[data-international-fields]');const flag=line.querySelector('[data-international-flag]');const rationale=line.querySelector('[data-deductibility-rationale]');const marker=line.querySelector('[data-rationale-required-marker]');const requiredTaxCodes=@json($user_specified_deductibility_tax_code_ids);const sync=()=>{const active=select.selectedOptions[0]?.dataset.international==='1';const rationaleRequired=active&&requiredTaxCodes.includes(select.value);fields.classList.toggle('hidden',!active);flag.value=active?'1':'0';rationale.required=rationaleRequired;marker.classList.toggle('hidden',!rationaleRequired);};select.addEventListener('change',sync);sync();});</script>
